INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(27601, '1 Corinthians 15:16', '1 Corinthians', 15, 16, '&nbsp;ځکه چې کۀ مړى نۀ راژوندى کيږى نو بيا مسيح هم راژوندے شوے نۀ دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27602, '1 Corinthians 15:17', '1 Corinthians', 15, 17, '&nbsp;او کۀ چرې مسيح نۀ وو راژوندے شوے نو ستاسو ايمان عبث دے او تاسو اوس هم په خپلو زړو ګناهونو کښې راګېر يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27603, '1 Corinthians 15:18', '1 Corinthians', 15, 18, '&nbsp;او بيا دا هم هغوئ څوک چې په مسيح کښې مړۀ شوى دى هغوئ هم هلاک شوى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27604, '1 Corinthians 15:19', '1 Corinthians', 15, 19, '&nbsp;کۀ چرې زمونږ اُميد په مسيح صرف د دې ژوند دپاره وى نو بيا مونږ په ټولو انسانانو کښې قابل رحم يُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27605, '1 Corinthians 15:20', '1 Corinthians', 15, 20, '&nbsp;خو په حقيقت کښې مسيح د مړو نه بيا راژوندے شوے دے. دغه شان هغه د مړو نه اولنے ژوندے شوے انسان دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27606, '1 Corinthians 15:21', '1 Corinthians', 15, 21, '&nbsp;لکه څنګه چې د يو انسان په سبب په دُنيا مرګ راغلو نو داسې د يو انسان په سبب د مړو نه بيا راژوندى کېدل راغلل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27607, '1 Corinthians 15:22', '1 Corinthians', 15, 22, '&nbsp;او لکه څنګه چې ټول خلق په آدم کښې مړۀ کيږى، نو دغه شان به ټول په مسيح کښې بيا راژوندى کيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27608, '1 Corinthians 15:23', '1 Corinthians', 15, 23, '&nbsp;خو د راژوندى کېدو خپل ترتيب دے، اول مسيح راژوندے شوے دے، او چې کله مسيح بيا راشى نو د هغۀ خلق به هم راژوندى شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27609, '1 Corinthians 15:24', '1 Corinthians', 15, 24, '&nbsp;بيا به آخرت راشى. کله چې مسيح ټول حکمرانان، ټول اختيارونه او قدرتونه تباه کړى نو د هغې نه پس به هغه بادشاهى خُدائ پلار ته حواله کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27610, '1 Corinthians 15:25', '1 Corinthians', 15, 25, '&nbsp;ځکه چې هغه به تر هغې ضرور بادشاهى کوى ترڅو چې خپل ټول دشمنان د خپلو پښو لاندې کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27611, '1 Corinthians 15:26', '1 Corinthians', 15, 26, '&nbsp;آخرى دشمن کوم چې به نيست او نابود کړى، هغه مرګ دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27612, '1 Corinthians 15:27', '1 Corinthians', 15, 27, '&nbsp;ځکه چې ”خُدائ پاک هغۀ ته په هر څيز پوره اختيار ورکړے دے.“ نو چې کله کِتابِ مقدس داسې فرمائى، چې هغۀ په هر څيز پوره اختيار ورکړے دے، نو مطلب دا نۀ دے چې په خُدائ پاک يې هم اختيار دے، چا چې خپل اختيار مسيح ته ورکړے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27613, '1 Corinthians 15:28', '1 Corinthians', 15, 28, '&nbsp;کله چې ټول څيزونه د هغۀ د حکم لاندې شول نو زوئ به په خپله هم د خُدائ پاک د حکم لاندې شى چا چې ټول څيزونه د هغۀ د حکم لاندې کړى دى نو هم دا خُدائ پاک به د ټولو مالِک وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27614, '1 Corinthians 15:29', '1 Corinthians', 15, 29, '&nbsp;نو کۀ چرې داسې وى نو بيا به هغه خلق څۀ کوى څوک چې د مړو دپاره بپتسمه اخلى؟ کۀ چرې مړى نۀ راژوندى کيږى، نو بيا ولې خلق د هغوئ دپاره بپتسمه اخلى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27615, '1 Corinthians 15:30', '1 Corinthians', 15, 30, '&nbsp;او ولې مونږ هر وخت خپل ځان په خطره کښې اچوو؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27616, '1 Corinthians 15:31', '1 Corinthians', 15, 31, '&nbsp;زما وروڼو او خوېندو، زۀ تاسو ته دا وايم چې زۀ هره ورځ مرګ سره لوبې کوم او دا داسې رښتيا خبره ده لکه څنګه چې زۀ په تاسو زمونږ په مالِک عيسىٰ مسيح کښې فخر کوم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27617, '1 Corinthians 15:32', '1 Corinthians', 15, 32, '&nbsp;کۀ صرف د انسانى اُميد دپاره زۀ په اِفِسوس کښې د وحشتناکو ځناورو سره وجنګېدلم نو د دې نه ما ته څۀ فائده حاصله شوه؟ کۀ مړى بيا نۀ راژوندى کيږى نو ”مونږ له ښۀ خوراک څښاک په کار دے، ځکه چې سبا به مړۀ کيږُو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27618, '1 Corinthians 15:33', '1 Corinthians', 15, 33, '&nbsp;دوکه کېږئ مه، ځکه چې د بدو ملګرتيا د انسان ښۀ عادتونه خرابوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27619, '1 Corinthians 15:34', '1 Corinthians', 15, 34, '&nbsp;په پوره هوش او فکر کښې راشئ او نوره ګناه مۀ کوئ. ځکه زۀ دا ستاسو د شرمېدلو دپاره وايم چې په تاسو کښې څۀ خلقو ته د خُدائ پاک په حقله عِلم نشته.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27620, '1 Corinthians 15:35', '1 Corinthians', 15, 35, '&nbsp;خو څوک به تپوس وکړى چې، ”مړى څنګه راژوندى کيږى او د هغوئ بدن به څۀ قِسم وى؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27621, '1 Corinthians 15:36', '1 Corinthians', 15, 36, '&nbsp;اے نادانه، کوم تخم چې تۀ کَرې نو ترڅو چې هغه مړ نۀ شى تر هغې نۀ ژوندے کيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27622, '1 Corinthians 15:37', '1 Corinthians', 15, 37, '&nbsp;او څۀ چې تاسو کَرئ دا تاسو تيار بوټى نۀ کَرئ بلکې صرف د تخم دانه کَرئ کۀ هغه د غنم وى يا د څۀ بل څيز وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27623, '1 Corinthians 15:38', '1 Corinthians', 15, 38, '&nbsp;خو خُدائ پاک دې ته يو وجود ورکوى چې هغۀ ورته منتخب کړے وى او هر قسم تخم ته هغه خپل خپل وجود ورکوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27624, '1 Corinthians 15:39', '1 Corinthians', 15, 39, '&nbsp;دغه شان غوښه هم يو شان نۀ وى بلکې د انسانانو غوښه يو قِسم وى او د څاروو بل او د مارغانو بل او د کبانو غوښه بل قِسم وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27625, '1 Corinthians 15:40', '1 Corinthians', 15, 40, '&nbsp;هم دغه شان آسمانى او زمکنى وجودونه هم شته، او د آسمانى وجود ښائست يو قسم او د زمکنى وجود بل شان وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27626, '1 Corinthians 15:41', '1 Corinthians', 15, 41, '&nbsp;هم دغه شان د نمر او د سپوږمۍ او د ستورو په ښائست کښې فرق وى، او بله دا چې د يو ستورى ښائست د بل نه مختلف وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27627, '1 Corinthians 15:42', '1 Corinthians', 15, 42, '&nbsp;نو بيا د مړو راژوندى کېدل هم دغه شان وى، د فنا په حالت کښې ښخ کړے شى او په غېر فانى حالت کښې راژوندى کيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27628, '1 Corinthians 15:43', '1 Corinthians', 15, 43, '&nbsp;د ذلالت په حالت کښې ښخيږى او د ښائست په حالت کښې راژوندى کيږى، دا په کمزورتيا کښې ښخ شى او په طاقت کښې راژوندى شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27629, '1 Corinthians 15:44', '1 Corinthians', 15, 44, '&nbsp;دا جسمانى وجود ښخ شى او روحانى وجود راژوندے شى. چې جسمانى وجود شته نو روحانى وجود هم شته.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27630, '1 Corinthians 15:45', '1 Corinthians', 15, 45, '&nbsp;هم دغه شان ليکلى دى، ”اول سړے، يعنې آدم ژوندے نفس جوړ شو، خو آخرى آدم ژوندون ورکوونکے روح جوړ شو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27631, '1 Corinthians 15:46', '1 Corinthians', 15, 46, '&nbsp;اول جسمانى او بيا روحانى وجود پېدا کيږى يعنې وجود اول جسمانى، او بيا روحانى شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27632, '1 Corinthians 15:47', '1 Corinthians', 15, 47, '&nbsp;اولنے انسان يعنې آدم د خاورو نه جوړ شوے وو، او دوېم انسان آسمانى دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27633, '1 Corinthians 15:48', '1 Corinthians', 15, 48, '&nbsp;او د زمکې خلق لکه د اول انسان په شان د خاورو دى، او آسمانى خلق لکه د هغه آسمانى انسان په شان دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27634, '1 Corinthians 15:49', '1 Corinthians', 15, 49, '&nbsp;او څنګه چې مونږ د دې زمکنى انسان په صورت جوړ شوى يُو دغه شان به د آسمانى انسان په صُورت کښې هم شُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27635, '1 Corinthians 15:50', '1 Corinthians', 15, 50, '&nbsp;زما وروڼو او خوېندو، زما مطلب دا دے چې دا جسمانى بدن د خُدائ پاک د بادشاهۍ وارث کېدے نۀ شى، او نۀ فانى کېدونکى د غېر فانى کېدونکى وارث کېدے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27636, '1 Corinthians 15:51', '1 Corinthians', 15, 51, '&nbsp;غوږ شئ، زۀ به درته يوه د راز خبره وکړم چې مونږ ټول خو به نۀ مرو بلکې مونږ ټول به بدل شُو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27637, '1 Corinthians 15:52', '1 Corinthians', 15, 52, '&nbsp;او د آخرى بيګل د آواز سره په يوه لحظه او د سترګو په رپ کښې به مړى په غېر فانى حالت کښې راژوندى شى، او مونږ به بدل شُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27638, '1 Corinthians 15:53', '1 Corinthians', 15, 53, '&nbsp;ځکه چې دا فانى کېدونکے بدن به ضرور غېر فانى لباس واچوى او دا ختمېدونکے بدن به د ابدى ژوندون لباس واچوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27639, '1 Corinthians 15:54', '1 Corinthians', 15, 54, '&nbsp;کله چې دا فانى بدن غېر فانى، او دا فنا کېدونکے بدن ابدى لباس واچوى، بيا به هغه قول پوره شى چې ليکلے شوى دى چې، ”په مرګ فتح غالبه شوه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27640, '1 Corinthians 15:55', '1 Corinthians', 15, 55, '&nbsp;”اے مرګه، ستا فتح څۀ شوه؟ اے مرګه، ستا د طاقت هغه لشه څۀ شوه؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27641, '1 Corinthians 15:56', '1 Corinthians', 15, 56, '&nbsp;د مرګ لشه ګناه ده او د ګناه طاقت شريعت دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27642, '1 Corinthians 15:57', '1 Corinthians', 15, 57, '&nbsp;خو د خُدائ پاک شُکر دے چې هغۀ مونږ ته د مالِک عيسىٰ مسيح په وسيله فتح راکوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27643, '1 Corinthians 15:58', '1 Corinthians', 15, 58, '&nbsp;نو اے زما خوږو وروڼو او خوېندو، ټينګ او قائم اوسئ او همېشه د مالِک په کار کښې بوخت اوسئ ځکه چې تاسو ته پته ده چې په مالِک کښې ستاسو خوارى بې‌فائدې نۀ ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27644, '1 Corinthians 16:1', '1 Corinthians', 16, 1, '&nbsp;اوس د هغې چندې په حقله چې د مقدسينو دپاره کيږى تاسو به په هغه هداياتو عمل کوئ چې ما د ګلتيانو جماعتونو ته ورکړى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27645, '1 Corinthians 16:2', '1 Corinthians', 16, 2, '&nbsp;د هرې هفتې په اوله ورځ دې په تاسو کښې هر يو کس د خپلې ګټې نه د خپل ځان سره څۀ نا څۀ جمع کوى، د دې دپاره چې کله زۀ درشم چې د چندې کولو حاجت ما ته نۀ وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27646, '1 Corinthians 16:3', '1 Corinthians', 16, 3, '&nbsp;او زۀ چې کله درشم نو زۀ به هغه کسانو ته چې تاسو ته قابل اعتماد وى د پېژندګلو خطونه وليکم چې يروشلم ته ستاسو چنده يوسى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27647, '1 Corinthians 16:4', '1 Corinthians', 16, 4, '&nbsp;او کۀ دا مناسب وى چې زۀ هم لاړ شم نو هغوئ به ما سره يو ځائ لاړ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27648, '1 Corinthians 16:5', '1 Corinthians', 16, 5, '&nbsp;زۀ به د مِکدونيه د تېرېدو نه وروستو تاسو له درشم ځکه چې زما اراده ده چې د مِکدونيه په لاره هلته لاړ شم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27649, '1 Corinthians 16:6', '1 Corinthians', 16, 6, '&nbsp;او کېدے شى چې زۀ تاسو سره پاتې شم او ژمے تاسو سره تير کړم نو چې بيا زۀ چرته ځم نو تاسو به مې هلته رُخصت کړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27650, '1 Corinthians 16:7', '1 Corinthians', 16, 7, '&nbsp;ځکه زۀ اوس په لاره کښې تاسو سره ملاقات کول نۀ غواړم بلکې زما دا اُميد دے کۀ مالِک وغوښتل نو څۀ وخت به تاسو سره تير کړم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27651, '1 Corinthians 16:8', '1 Corinthians', 16, 8, '&nbsp;خو زۀ به د پنځوسمې اختر پورې په اِفِسوس کښې پاتې يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27652, '1 Corinthians 16:9', '1 Corinthians', 16, 9, '&nbsp;ځکه چې زما دپاره د ښۀ خِدمت يو لوئ ور کولاو دے او هلته مخالفين هم ډېر دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
