(27697, '2 Corinthians 2:6', '2 Corinthians', 2, 6, '&nbsp;د داسې سړى دپاره دغه سزا کافى ده کومه چې هغۀ د ډېرو خلقو نه وموندله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27698, '2 Corinthians 2:7', '2 Corinthians', 2, 7, '&nbsp;نو اوس د دې په ځائ تاسو ته په کار دى چې د هغۀ قصور معاف کړئ او تسلى ورکړئ هسې نه چې هغه د ډيرې پرېشانۍ په وجه غرق شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27699, '2 Corinthians 2:8', '2 Corinthians', 2, 8, '&nbsp;نو د دې دپاره زۀ تاسو ته خواست کوم چې هغۀ ته خپله مينه بيا ښکاره کړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27700, '2 Corinthians 2:9', '2 Corinthians', 2, 9, '&nbsp;ما هم په دې وجه دا وليکل چې تاسو وآزمائيم چې تاسو په ټولو خبرو کښې زما تابعدار يئ او کۀ نه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');